def _get_joints(agent_components):
    if isinstance(agent_components, dict):
        return agent_components.get("joints", [])
    return []

def build_agent(sandbox):
    # Torso (chassis): lightweight beam centered at (10, 2.5)
    chassis = sandbox.add_beam(x=10.0, y=2.5, width=2.0, height=0.2, angle=0, density=1.0)
    sandbox.set_material_properties(chassis, restitution=0.1, friction=0.2)

    # Wheel parameters: radius=0.2m, density=0.5kg/m³
    wheel_radius = 0.2
    wheel_density = 0.5

    # Left wheel: centered at (9.0, 2.0), attached to chassis at (9.0, 2.5)
    wheel1 = sandbox.add_wheel(x=9.0, y=2.0, radius=wheel_radius, density=wheel_density)
    sandbox.set_material_properties(wheel1, restitution=0.1, friction=0.5)

    # Right wheel: centered at (11.0, 2.0), attached to chassis at (11.0, 2.5)
    wheel2 = sandbox.add_wheel(x=11.0, y=2.0, radius=wheel_radius, density=wheel_density)
    sandbox.set_material_properties(wheel2, restitution=0.1, friction=0.5)

    # Connect wheels to chassis with pivot joints, with joint limits matching the environment's range
    joint1 = sandbox.add_joint(chassis, wheel1, (9.0, 2.5), type='pivot', lower_limit=-0.2244, upper_limit=0.2244)
    joint2 = sandbox.add_joint(chassis, wheel2, (11.0, 2.5), type='pivot', lower_limit=-0.2244, upper_limit=0.2244)

    return {"body": chassis, "joints": [joint1, joint2]}

def agent_action(sandbox, agent_body, step_count):
    joints = _get_joints(agent_body)
    if not joints:
        return

    torso = agent_body.get("body")
    if torso is None:
        return

    # Apply motor speed to both joints to rotate wheels and propel forward motion
    if torso.position.x > 23.0:
        rotation_speed = 0.0
    else:
        rotation_speed = -5.0  # Moderate speed for forward motion without over-rotation

    for j in joints:
        sandbox.set_motor(j, rotation_speed, max_torque=2000.0)
